with engine.connect() as conn:
    conn.execute(text(CREATE_TABLE))

    for slug, name, svg, tags_csv, tiers_csv in ASSETS:
        # Convert CSV strings → Python lists (psycopg2 adapts these to Postgres arrays)
        tags_list  = [t.strip() for t in tags_csv.split(",") if t.strip()]
        tiers_list = [t.strip() for t in tiers_csv.split(",") if t.strip()]

        # Check if already exists
        existing = conn.execute(
            text("SELECT id FROM assets WHERE slug = :slug"),
            {"slug": slug}
        ).fetchone()
        if existing:
            print(f"  skip (exists): {slug}")
            continue

        conn.execute(
            text("""
                INSERT INTO assets (slug, name, svg_content, tags, tier_allowed)
                VALUES (:slug, :name, :svg, :tags, :tiers)
            """),
            {
                "slug": slug,
                "name": name,
                "svg": svg,
                "tags": tags_list,
                "tiers": tiers_list,
            }
        )
        print(f"  inserted: {slug}")

    conn.commit()

print(f"\n[seed] Done! Inserted/verified {len(ASSETS)} assets.")

